  $('#create-next-bulletin').hidden=current?.status!=='published';$('#create-next-bulletin').disabled=working||needsRefresh||!canAction(access,church,'website_weekly','create');
  $('#reload-bulletins').disabled=working;$('#new-bulletin').disabled=working||needsRefresh||!canAction(access,church,'website_weekly','create');
  document.querySelectorAll('.bulletin-choice').forEach(control=>control.disabled=working||needsRefresh);
