async function generateReel({fromSubmit=false}={}){
  const views=fromSubmit?[reelProgress,submitProgress]:[reelProgress];
  views.forEach((view,index)=>view.start({history:`reel:${church}`,baselineSeconds:60,recordHistory:index===0,label:'IG 影片製作中…',description:'正在準備圖片與音樂。'}));
  const update=data=>views.forEach(view=>view.update(data));
  try{
    if(!current?.hero_image_path)throw new Error('請先儲存主日預告圖片，再產生 IG 影片。');
    const {createWeeklyReel,reelSupported}=await import('./weekly-reel.mjs?v=20261010-media-progress1');
    if(!reelSupported())throw new Error('reel_unsupported');
    const track=selectedMusic(),blob=await createWeeklyReel({imageUrl:publicImage(current.hero_image_path),title:$('#bulletin-title').value.trim(),subtitle:$('#bulletin-subtitle').value.trim(),serviceDate:$('#service-date').value,audioUrl:track?publicImage(track.storage_path):'',audioStart:Number($('#music-start').value)||0,onProgress:({phase,completed,total})=>update({label:'IG 影片製作中…',description:phase==='frames'?`正在合成影片：${completed}／${total} 個影格。`:phase==='finalize'?'影格已合成，正在完成影片檔案。':'正在載入圖片與音樂。'})}),path=`${church}/weekly/${current.id}/reel-${Date.now()}.mp4`;
    update({label:'正在上傳 IG 影片…',description:'影片已合成，正在保存到週報。'});
    const uploaded=await db.storage.from(BUCKET).upload(path,blob,{contentType:'video/mp4',cacheControl:'3600'});
    if(uploaded.error)throw new Error('IG 影片上傳失敗，請稍後重試。');
    const old=current.reel_video_path,session=await db.auth.getSession(),token=session.data.session?.access_token;
    if(!token)throw new Error('登入已失效，請重新登入。');
    update({label:'正在保存 IG 影片…',description:'檔案已上傳，正在確認週報中的影片紀錄。'});
    const response=await fetch(INSTAGRAM_ENDPOINT,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(30000),body:JSON.stringify({action:'save_reel',church,bulletinId:current.id,reelEnabled:$('#reel-enabled').checked,reelVideoPath:path,reelAudioPath:track?.storage_path||null,reelAudioStart:Number($('#music-start').value)||0,reelCaption:$('#reel-caption').value.trim()||defaultReelCaption()})}),result=await apiResult(response),data=result.bulletin;
    if(!response.ok||!data)throw new Error('IG 影片預覽尚未確認保存，請重新載入確認。');
    if(old&&old!==path)await db.storage.from(BUCKET).remove([old]);
    current=data;showReel();$('#reel-state').textContent=track?'預覽已產生，包含背景音樂。':'預覽已產生（無音樂）。';
    views.forEach(view=>view.finish('IG 影片已保存，可播放預覽。'));setStatus('IG 影片預覽已更新，送審後牧師、師母也能播放確認。','success');return true;
  }catch(error){
    const text=error.message==='reel_unsupported'?'這個瀏覽器目前無法合成 IG 影片，可先送審週報與圖卡。':error.message==='reel_image'?'IG 影片使用的預告圖片暫時無法載入。':error.message==='reel_encode'?'IG 影片編碼未完成。':error.message||'IG 影片製作未完成。';
    views.forEach(view=>view.fail(text));setStatus(text,'error');$('#reel-state').textContent=text;return false;
  }
}

